"""Exact sqrt(2) geometry of the standard basis configuration in R^n."""
from __future__ import annotations
import math
from itertools import combinations

def basis_vector(n: int, i: int) -> tuple[float, ...]:
    return tuple(1.0 if k == i else 0.0 for k in range(n))

def euclidean_distance(x: tuple[float, ...], y: tuple[float, ...]) -> float:
    return math.sqrt(sum((a - b) ** 2 for a, b in zip(x, y)))

def verify_sqrt2_geometry(n: int) -> bool:
    pts = [basis_vector(n, i) for i in range(n)]
    target = math.sqrt(2.0)
    return all(abs(euclidean_distance(pts[i], pts[j]) - target) < 1e-12
               for i, j in combinations(range(n), 2))

if __name__ == "__main__":
    for n in range(2, 9):
        print(f"n={n}: all pairwise distances = sqrt(2)? {verify_sqrt2_geometry(n)}")

"""Simplex counts of the standard-basis Vietoris-Rips complex: brute force vs closed form."""
from __future__ import annotations
import math
from itertools import combinations

SQRT2 = math.sqrt(2.0)

def basis_vector(n: int, i: int) -> tuple[float, ...]:
    return tuple(1.0 if k == i else 0.0 for k in range(n))

def dist(x: tuple[float, ...], y: tuple[float, ...]) -> float:
    return math.sqrt(sum((a - b) ** 2 for a, b in zip(x, y)))

def count_bruteforce(n: int, r: float) -> int:
    pts = [basis_vector(n, i) for i in range(n)]
    total = 0
    for mask in range(1 << n):
        sub = [i for i in range(n) if (mask >> i) & 1]
        ok = all(dist(pts[a], pts[b]) <= r + 1e-12 for a, b in combinations(sub, 2))
        total += int(ok)
    return total

def count_closed_form(n: int, r: float) -> int:
    return 2 ** n if r + 1e-12 >= SQRT2 else n + 1

if __name__ == "__main__":
    for n in range(1, 9):
        for r, label in [(SQRT2 - 0.01, "below"), (SQRT2, "at")]:
            bf, cf = count_bruteforce(n, r), count_closed_form(n, r)
            print(f"n={n} r {label} sqrt2: brute={bf} closed={cf} match={bf==cf}")

"""Graded rate gamma(c) contrasted with the flat (equidistant) rate 0."""
from __future__ import annotations
import math

SQRT2 = math.sqrt(2.0)

def gamma(c: float) -> float:
    return (SQRT2 / c - 1.0) / (SQRT2 - 1.0)

def graded_exponent(n: int, c: float) -> int:
    return math.floor(n * gamma(c))

if __name__ == "__main__":
    n = 100
    for c in [1.0, 1.1, 1.2, 1.3, 1.4, 1.41, 1.414]:
        print(f"c={c:.3f}: gamma={gamma(c):.5f}, floor(n*gamma)={graded_exponent(n, c)}")
    print("Flat equidistant configuration: gamma == 0 (no sub-threshold content).")

