    require c >= 1
    lower <- (2^n if t >= c*sqrt(2) else NONE)   # completeness at sqrt(2)
    upper <- (n+1 if c*t < sqrt(2) else NONE)     # soundness below threshold
    return (lower, upper)

function GRADED_RATE(c):
    require 1 <= c < sqrt(2)
    return (sqrt(2)/c - 1) / (sqrt(2) - 1)

function GRADED_LOWER_BOUND(n, c):
    g <- GRADED_RATE(c)
    return 2^floor(n * g)

