from __future__ import annotations
import math

SQRT2: float = math.sqrt(2.0)

def graded_rate(c: float) -> float:
    """Effective graded exponential rate gamma(c) = (sqrt(2)/c - 1)/(sqrt(2) - 1)
    on the regime c in [1, sqrt(2)). Satisfies 0 < gamma(c) <= 1 and
    gamma(c) -> 0 as c -> sqrt(2)^-."""
    if not (1.0 <= c < SQRT2):
        raise ValueError("c must lie in [1, sqrt(2))")
    return (SQRT2 / c - 1.0) / (SQRT2 - 1.0)

def graded_lower_bound(n: int, c: float) -> int:
    """Sub-threshold exponential lower bound 2**floor(n*gamma(c)) on the number
    of simplices any c-approximation must store, for the graded construction."""
    return 2 ** math.floor(n * graded_rate(c))
